package com.aegis.erp.modules.planilla.cuentabancaria;
import com.aegis.erp.common.exception.*;import com.aegis.erp.common.export.DocumentExportService;import com.aegis.erp.modules.planilla.empleado.EmpleadoOptionResponse;import com.aegis.erp.modules.planilla.entity.*;import com.aegis.erp.modules.planilla.repository.*;import java.time.*;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class CuentaBancariaService{private final CuentaBancariaEmpleadoRepository cuentas;private final EmpleadoRepository empleados;private final BancoRepository bancos;private final DocumentExportService exports;private final Clock clock;public CuentaBancariaService(CuentaBancariaEmpleadoRepository cuentas,EmpleadoRepository empleados,BancoRepository bancos,DocumentExportService exports,Clock clock){this.cuentas=cuentas;this.empleados=empleados;this.bancos=bancos;this.exports=exports;this.clock=clock;}
 @Transactional(readOnly=true)public List<CuentaBancariaResponse>listar(String search){String q=norm(search);return cuentas.findAll().stream().map(this::response).filter(x->q.isEmpty()||(x.empleadoNombre()+" "+x.bancoNombre()+" "+x.numeroCuenta()).toLowerCase(Locale.ROOT).contains(q)).toList();}@Transactional public CuentaBancariaResponse crear(CuentaBancariaRequest r,String user){return save(CuentaBancariaEmpleado.crear(empleado(r.empleadoId()),banco(r.bancoId()),r.numeroCuenta().trim(),r.activa(),user,LocalDateTime.now(clock)));}@Transactional public CuentaBancariaResponse modificar(Long id,CuentaBancariaRequest r,String user){var e=find(id);e.modificar(empleado(r.empleadoId()),banco(r.bancoId()),r.numeroCuenta().trim(),r.activa(),user,LocalDateTime.now(clock));return save(e);}@Transactional public void eliminar(Long id){var e=find(id);try{cuentas.delete(e);cuentas.flush();}catch(DataIntegrityViolationException ex){throw new BusinessConflictException("No se puede eliminar la cuenta porque tiene información asociada.");}}
 @Transactional(readOnly=true)public List<EmpleadoOptionResponse>empleados(String search){String q=norm(search);return empleados.findAll().stream().filter(e->q.isEmpty()||(e.getId()+" "+e.getPersona().getNombre()+" "+e.getPersona().getApellido()).toLowerCase(Locale.ROOT).contains(q)).limit(50).map(e->new EmpleadoOptionResponse(e.getId(),"#"+e.getId()+" — "+e.getPersona().getNombre()+" "+e.getPersona().getApellido())).toList();}@Transactional(readOnly=true)public List<EmpleadoOptionResponse>bancos(){return bancos.findAll().stream().map(b->new EmpleadoOptionResponse(b.getId(),b.getNombre())).toList();}
 @Transactional(readOnly=true)public byte[]excel(String s){return exports.excel("Cuentas bancarias",headers(),rows(s));}@Transactional(readOnly=true)public byte[]pdf(String s){return exports.pdf("Cuentas bancarias de empleados",headers(),rows(s));}private List<String>headers(){return List.of("ID","Empleado","Banco","Número de cuenta","Activa");}private List<List<?>>rows(String s){return listar(s).stream().<List<?>>map(x->List.of(x.id(),x.empleadoNombre(),x.bancoNombre(),x.numeroCuenta(),x.activa())).toList();}
 private CuentaBancariaResponse save(CuentaBancariaEmpleado e){try{return response(cuentas.saveAndFlush(e));}catch(DataIntegrityViolationException ex){throw new BusinessConflictException("No fue posible guardar la cuenta por una restricción de integridad.");}}private CuentaBancariaResponse response(CuentaBancariaEmpleado e){return new CuentaBancariaResponse(e.getId(),e.getEmpleado().getId(),e.getEmpleado().getPersona().getNombre()+" "+e.getEmpleado().getPersona().getApellido(),e.getBanco().getId(),e.getBanco().getNombre(),e.getNumeroCuenta(),e.getActiva());}private CuentaBancariaEmpleado find(Long id){return cuentas.findById(id).orElseThrow(()->new ResourceNotFoundException("Cuenta bancaria no encontrada."));}private Empleado empleado(Long id){return empleados.findById(id).orElseThrow(()->new ResourceNotFoundException("Empleado no encontrado."));}private Banco banco(Long id){return bancos.findById(id).orElseThrow(()->new ResourceNotFoundException("Banco no encontrado."));}private String norm(String s){return s==null?"":s.trim().toLowerCase(Locale.ROOT);}}
